import re
from itertools import groupby
from zipfile import BadZipfile

import openpyxl
from natsort import natsorted
from robot.api import logger

from .exception import MeasurementException, WrongColumnName

import _csv
import traceback


class Measurements(object):
    MEASUREMENT_XLS_HEADER_ID = 7

    def __init__(self):
        self.measurements = None
        self._abbreviations = None

    def load_measurements(self, measurements_paths, **kwargs):
        """Prepare measurement data."""
        if measurements_paths['measurements'].endswith('.csv'):
            self.load_measurement_csv_file(measurements_paths['measurements'], **kwargs)
        else:
            self.load_measurement_xls_file(measurements_paths['measurements'], **kwargs)

        if measurements_paths['abbr'].endswith('.csv'):
            self.load_measurement_csv_dictionary(measurements_paths['abbr'])
        else:
            self.load_measurement_dictionary(measurements_paths['abbr'])

    def load_measurement_xls_file(self, measurement_file_path, **kwargs):
        """
        Parse NIDD exported spreadsheet.
        :param measurement_file_path: Path to xls file
        """
        try:
            workbook = openpyxl.load_workbook(measurement_file_path, read_only=False)
            sheet = workbook.active

            sheet.delete_rows(1, amount=self.MEASUREMENT_XLS_HEADER_ID)

            sheet = self._filter_by(sheet, **kwargs)

            pi_id_column_index = self._get_column_index(sheet, 'PI ID')
            pi_id_column = self._get_column_values(sheet, pi_id_column_index, start_row_idx=2)

            measurement_column_index = self._get_column_index(sheet, 'Measurement')
            measurement_column = self._get_column_values(sheet, measurement_column_index, start_row_idx=2)

            self.measurements = self._group_measurements(pi_id_column, measurement_column)
        except IOError:
            raise MeasurementException("The specified path does not exist")
        except BadZipfile:
            raise MeasurementException("Unsupported format, or corrupt file")
        except ValueError as e:
            raise WrongColumnName("Cannot find column: {col}".format(col=repr(e)))

    def load_measurement_csv_file(self, measurement_file_path, **kwargs):
        """
        Parse NIDD exported spreadsheet.
        :param measurement_file_path: Path to csv file
        """
        try:
            workbook = openpyxl.Workbook()
            sheet = workbook.active

            with open(measurement_file_path, 'r') as csvfile:
                csvreader = _csv.reader(csvfile, delimiter=';')
                wb_row = 0
                for row in csvreader:
                    wb_row += 1
                    wb_column = 0
                    for item in row:
                        wb_column += 1
                        sheet.cell(row=wb_row, column=wb_column, value=item)

            sheet = self._filter_by(sheet, **kwargs)

            pi_id_column_index = self._get_column_index(sheet, 'PI ID')
            pi_id_column = self._get_column_values(sheet, pi_id_column_index, start_row_idx=2)

            measurement_column_index = self._get_column_index(sheet, 'Measurement')
            measurement_column = self._get_column_values(sheet, measurement_column_index, start_row_idx=2)

            self.measurements = self._group_measurements(pi_id_column, measurement_column)

        except _csv.Error:
            print(traceback.format_exc())
            raise MeasurementException("Check if loaded file is in correct csv format and contains data")
        except ValueError as e:
            raise WrongColumnName("Cannot find column: {col}".format(col=repr(e)))

    def load_measurement_dictionary(self, dictionary_file_path):
        """
        Load dictionary containing measurements abbreviations used in SCF
        :param dictionary_file_path: Path to xls dictionary file
        """
        try:
            workbook = openpyxl.load_workbook(dictionary_file_path, read_only=False)
            sheet = workbook.active

            abbreviation_column_index = self._get_column_index(sheet, 'Abbreviation')
            abbreviation_column = self._get_column_values(sheet, abbreviation_column_index, start_row_idx=2)

            measurement_column_index = self._get_column_index(sheet, 'Measurement')
            measurement_column = self._get_column_values(sheet, measurement_column_index, start_row_idx=2)
            measurement_column = (item.lower() for item in measurement_column)

            self._abbreviations = dict(zip(measurement_column, abbreviation_column))
        except IOError:
            raise MeasurementException("The specified path does not exist")
        except BadZipfile:
            raise MeasurementException("Unsupported format, or corrupt file")
        except ValueError as e:
            raise WrongColumnName("Cannot find column: {col}".format(col=repr(e)))

    def load_measurement_csv_dictionary(self, dictionary_file_path):
        """
        Load dictionary containing measurements abbreviations used in SCF
        :param dictionary_file_path: Path to csv dictionary file
        """
        try:
            workbook = openpyxl.Workbook()
            sheet = workbook.active

            with open(dictionary_file_path, 'r') as csvfile:
                csvreader = _csv.reader(csvfile, delimiter=';')
                wb_row = 0
                for row in csvreader:
                    wb_row += 1
                    wb_column = 0
                    for item in row:
                        wb_column += 1
                        sheet.cell(row=wb_row, column=wb_column, value=item)

            abbreviation_column_index = self._get_column_index(sheet, 'Abbreviation')
            abbreviation_column = self._get_column_values(sheet, abbreviation_column_index, start_row_idx=2)

            measurement_column_index = self._get_column_index(sheet, 'Measurement')
            measurement_column = self._get_column_values(sheet, measurement_column_index, start_row_idx=2)
            measurement_column = (item.lower() for item in measurement_column)

            self._abbreviations = dict(zip(measurement_column, abbreviation_column))

        except _csv.Error:
            print(traceback.format_exc())
            raise MeasurementException("Check if loaded file is in correct csv format and contains data")
        except ValueError as e:
            raise WrongColumnName("Cannot find column: {col}".format(col=repr(e)))

    @staticmethod
    def _get_column_index(sheet, name, header_row_idx=1):
        """Get index (1-based) of a column with header `name`"""
        try:
            cell = next(cell for cell in sheet[header_row_idx] if cell.value == name)
            return cell.column
        except StopIteration:
            raise ValueError(name)

    @staticmethod
    def _get_column_values(sheet, col_idx, start_row_idx=1):
        """Get list of values of a column with index `col_idx` (1-based), starting with row start_row_idx"""
        return [cell.value for cell
                in next(sheet.iter_cols(min_col=col_idx, max_col=col_idx, min_row=start_row_idx))]

    def get_abbreviation(self, measurement_name):
        """
        Returns measurement name abbreviation.
        :param measurement_name: Full measurement name
        :return: Measurement name abbreviation
        """
        try:
            return self._abbreviations[measurement_name.lower()]
        except KeyError:
            raise MeasurementException("Measurement {mt} not found in abbreviation file".format(mt=measurement_name))

    @staticmethod
    def _group_measurements(column_1, column_2):
        # type: (List[str], List[str]) -> Dict[str, List[str]]
        """
        column_1 / pi_id_column
        [u'M8000C0', u'M8000C1', u'M8000C2', u'M8000C3',\
         u'M8001C0', u'M8001C1', u'M8001C2', u'M8001C3',\
         u'M8102C0', u'M8102C1', u'M8102C2', u'M8102C3']

        column_2 / measurement_column

        [u'LTE S1AP', u'LTE S1AP', u'LTE S1AP', u'LTE S1AP',\
         u'LTE Cell Load', u'LTE Cell Load', u'LTE Cell Load', u'LTE Cell Load',\
         u'Cat-M Mobility', u'Cat-M Mobility', u'Cat-M Mobility', u'Cat-M Mobility']

         will get turned into

         {u'Cat-M Mobility': [u'M8102C0', u'M8102C1', u'M8102C2', u'M8102C3'],
          u'LTE Cell Load': [u'M8001C0', u'M8001C1', u'M8001C2', u'M8001C3'],
          u'LTE S1AP': [u'M8000C0', u'M8000C1', u'M8000C2', u'M8000C3']}

        """
        return {k: natsorted(list(set(item[0] for item in group)))
                for k, group in groupby(zip(column_1, column_2), key=lambda item: item[1])}

    def _filter_by(self, sheet, **kwargs):
        # type: (Worksheet, Dict) -> Worksheet
        try:
            filtering_dict = self.__prepare_filtering_dict(kwargs)
            for column_header, pattern in filtering_dict.items():
                sheet = self._filter_by_value_in_column(sheet, column_header, pattern)

        except KeyError as e:
            raise WrongColumnName("Wrong column name {}".format(e))
        except AttributeError:
            return sheet
        else:
            return sheet

    @staticmethod
    def __prepare_filtering_dict(kwargs):
        # type: (Dict[str, str]) -> Dict[str, str]
        """
        for kwargs
        {'filtrate_key': 'Product_types,Category,Document_state',
        'filtrate_val': 'Flexi_SBTS|Flexi_AirScale,Customer,Published'}

        return
        {'Category': 'Customer', 'Document state': 'Published', 'Product types': 'Flexi SBTS|Flexi AirScale'}
        """
        filter_key = _derive_values_from_string("filtrate_key", kwargs)
        filter_value = _derive_values_from_string("filtrate_val", kwargs)
        if len(filter_key) != len(filter_value):
            logger.warn("Lists with parameters are not of equal lengths, it may result in incomplete filtering")
        filtering_dict = dict(zip(filter_key, filter_value))
        return filtering_dict

    def _filter_by_value_in_column(self, sheet, column_header, pattern):
        # type: (Worksheet, str, str) -> Worksheet
        """Keep rows that match `pattern` in a column with given `column header`"""

        tmp_workbook = openpyxl.Workbook()
        tmp_sheet = tmp_workbook.active

        # copy the header
        tmp_sheet.append(
            (cell.value for cell in sheet[1])
        )

        col_idx = self._get_column_index(sheet, column_header, header_row_idx=1)

        try:
            for row in sheet.iter_rows():
                if re.search(pattern, row[col_idx - 1].value):
                    tmp_sheet.append(
                        (cell.value for cell in row)
                    )
        except TypeError:
            print("TypeError: ", "column_id: ", row[col_idx -1], "value: ", row[col_idx -1].value)
            pass

        return tmp_sheet


def _derive_values_from_string(key, kwargs):
    # type: (str, Dict) -> List[str]
    """
    for

    kwargs
    {'filtrate_key': 'Product_types,Category,Document_state',
    'filtrate_val': 'Flexi_SBTS|Flexi_AirScale,Customer,Published'}

    return
    ['Product types', 'Category', 'Document state']

    (for key='filtrate_key')

    or return
    ['Flexi SBTS|Flexi AirScale', 'Customer', 'Published']

    (for key='filtrate_value')
    """
    return [_key.replace("_", " ").strip() for _key in kwargs.get(key).split(",")]
